    public void addOracleUsageMethodSetConnect(
            JavaChunk theJavaCode
            , String packageName
            , String authorName
            , String versionName
            , String commentField
            , String packageVisability
            , boolean debugMessages
            , boolean otherMessages
            , boolean stats
            , boolean comments
            , String javaNamingConvention
            , String oracleVersion
            , SingleNamespaceObject[] theSequences
            , String seq_class_name
            , String[] thingsToBeReconnected) {
        String sSetConnection = "setConnection";
        theJavaCode.print(" ");
        if (comments) {
            theJavaCode.print("/** ");
            theJavaCode.print("* Give all classes that have been instantiated a new database connection ");
            theJavaCode.print("* This undoes the effects of releaseResources");
            theJavaCode.print("* @param Connection theConnection ");
            theJavaCode.print("* @return boolean true if all went well otherwise false ");
            theJavaCode.print("*/ ");
        }
        theJavaCode.print(" ");
        theJavaCode.print("public boolean " + sSetConnection + "(Connection theConnection) ");
        theJavaCode.indent();
        theJavaCode.print("{ ");
        theJavaCode.print("boolean returnCode = true; ");
        theJavaCode.print("");
        if (debugMessages)
            theJavaCode.print("" + stheLog + ".debug(\"" + seq_class_name + " - Attempting to set connection\");");
        //theJavaCode.print("");
        theJavaCode.print("try ");
        theJavaCode.indent();
        theJavaCode.print("{ ");
        if (comments) theJavaCode.print("// We need to keep a copy of the connection in case an object which");
        if (comments) theJavaCode.print("// is currently null is instantiated later");
        theJavaCode.print("this.theConnection = theConnection;");

        for (int i = 0; i < thingsToBeReconnected.length; i++) {
            theJavaCode.print("");
            theJavaCode.print("if (" + thingsToBeReconnected[i] + " != null)");
            theJavaCode.indent();
            theJavaCode.print("{ ");
            theJavaCode.print(thingsToBeReconnected[i] + "." + sSetConnection + "(theConnection); ");
            theJavaCode.print("} ");
            theJavaCode.unIndent();
        }

        theJavaCode.print("} ");
        theJavaCode.unIndent();
        theJavaCode.print("catch (Exception e) ");
        theJavaCode.indent();
        theJavaCode.print("{ ");
        // (stats)theJavaCode.print("incErrorCount();");
        if (otherMessages) theJavaCode.print("" + stheLog + ".warning(e.toString()); ");
        theJavaCode.print("returnCode = false; ");
        theJavaCode.print("} ");
        theJavaCode.unIndent();
        theJavaCode.print("");

        theJavaCode.print("");
        theJavaCode.print("return(returnCode); ");
        theJavaCode.print("} ");
        theJavaCode.unIndent();
        theJavaCode.print("");


    }

