    public void addCommitMethods(JavaChunk theJavaCode, String factoryClassName, boolean debug, boolean comments) {
        theJavaCode.print(" ");

        if (comments) {
            theJavaCode.print("/**                                                        ");
            theJavaCode.print("* Commit changes to the database.    ");
            theJavaCode.print("* @throws CSDBException if something goes wrong. This is most likely to ");
            theJavaCode.print("* if <code>batchUpdateSize</code> is a value other than 1. ");
            theJavaCode.print("*/                                                         ");
        }
        theJavaCode.print("public void commit() throws CSDBException      ");
        theJavaCode.indent();
        theJavaCode.print("{                                  ");
        theJavaCode.print(" ");
        theJavaCode.print("if (theConnection != null)");
        theJavaCode.indent();
        theJavaCode.print("{                                  ");
        theJavaCode.print("try");
        theJavaCode.indent();
        theJavaCode.print("{");
        if (debug) theJavaCode.print("" + stheLog + ".debug(\"" + factoryClassName + " - Committing Changes\");");
        theJavaCode.print("theConnection.commit();");
        theJavaCode.print("}");
        theJavaCode.unIndent();
        theJavaCode.print("catch (java.sql.SQLException e)");
        theJavaCode.indent();
        theJavaCode.print("{");
        theJavaCode.print(stheLog + ".error(\"" + factoryClassName + " - Commit Failed:\");");
        theJavaCode.print(stheLog + ".error(e);");
        theJavaCode.print("CSDBException e2 = new CSDBException(e.getErrorCode(),e.getMessage(),\"commit\",\"" + factoryClassName + "\");");
        theJavaCode.print("throw(e2);");
        theJavaCode.print("}");
        theJavaCode.unIndent();
        theJavaCode.print("}                            ");
        theJavaCode.unIndent();
        theJavaCode.print("}                            ");
        theJavaCode.unIndent();

        theJavaCode.print(" ");

        if (comments) {
            theJavaCode.print("/**                                                        ");
            theJavaCode.print("* Rollback changes to the database.    ");
            theJavaCode.print("*/                                                         ");
        }
        theJavaCode.print("public void rollback() throws CSException      ");
        theJavaCode.indent();
        theJavaCode.print("{                                  ");
        theJavaCode.print(" ");
        theJavaCode.print("if (theConnection != null)");
        theJavaCode.indent();
        theJavaCode.print("{                                  ");
        theJavaCode.print("try");
        theJavaCode.indent();
        theJavaCode.print("{");
        if (debug) theJavaCode.print("" + stheLog + ".debug(\"" + factoryClassName + " - Rolling back changes\");");
        theJavaCode.print("theConnection.rollback();");
        theJavaCode.print("}");
        theJavaCode.unIndent();
        theJavaCode.print("catch (java.sql.SQLException e)");
        theJavaCode.indent();
        theJavaCode.print("{");
        theJavaCode.print(stheLog + ".error(\"" + factoryClassName + " - Rollback Failed:\");");
        theJavaCode.print(stheLog + ".error(e);");
        theJavaCode.print("throw (new CSDBException(e.getErrorCode(),e.getMessage(),\"rollback\",\"" + factoryClassName + "\"));");
        theJavaCode.print("}");
        theJavaCode.unIndent();
        theJavaCode.print("}                            ");
        theJavaCode.unIndent();
        theJavaCode.print("}                            ");
        theJavaCode.unIndent();


    }

