    void confirmDirectory(File testDirectory) throws CSException {

        if (!testDirectory.exists()) {
            mrLog.info("Directory " + testDirectory + " being created");
            if (!testDirectory.mkdirs()) {
                throw new CSException("Directory " + testDirectory.getAbsolutePath() + " can not be created");
            }
        } else
        // testDirectory exists
        {
            if (!testDirectory.canRead()) {
                throw new CSException(("Directory " + testDirectory.getAbsolutePath() + " can not be read"));
            }

            if (!testDirectory.canWrite()) {
                throw new CSException(("Directory " + testDirectory.getAbsolutePath() + " can not be written to"));
            }

            if (!testDirectory.isDirectory()) {
                throw new CSException(testDirectory.getAbsolutePath() + " is not a directory");
            }
        }

    }

