    boolean writeFile(File newFile, String[] fileContents) {
        boolean returnCode = true;

        if (writePhysicalFiles || newFile.getName().endsWith(TSQ) || newFile.getName().endsWith(procCodeSuffix)) {
            try {
                if (!newFile.getName().endsWith(TSQ) && !newFile.getName().endsWith(procCodeSuffix)) {
                    mrLog.debug("Writing file " + newFile.getAbsolutePath());
                }

                // Create new File Stream
                FileOutputStream theFileStream = new FileOutputStream(newFile);

                // Create new Printwriter
                PrintWriter thePrintWriter = new PrintWriter(theFileStream);

                for (int i = 0; i < fileContents.length; i++) {
                    thePrintWriter.println(fileContents[i]);
                }

                thePrintWriter.flush();
                theFileStream.flush();

                thePrintWriter.close();
                theFileStream.close();

                //thePrintWriter = null;
                //theFileStream = null;

            } catch (java.io.IOException e) {
                mrLog.syserror("Unexpected IO Error while writing file '" + newFile.getAbsolutePath() + "': " + e.getMessage(), true, true);
                returnCode = false;
            }
        }

        if (listener != null && newFile.getName().endsWith(".java")) {
            McpDbWizardEvent obEvent = new McpDbWizardEvent(McpDbWizardEvent.FILE_CREATED);
            obEvent.setThing(newFile);
            obEvent.setThing2(fileContents);
            listener.reportEvent(obEvent);
        } else if (listener != null && newFile.getName().endsWith(".sql")) {
            McpDbWizardEvent obEvent = new McpDbWizardEvent(McpDbWizardEvent.FILE_CREATED);
            obEvent.setThing(newFile);
            obEvent.setThing2(fileContents);
            listener.reportEvent(obEvent);
        } else if (listener != null && newFile.getName().endsWith(DOT_SH)) {
            McpDbWizardEvent obEvent = new McpDbWizardEvent(McpDbWizardEvent.FILE_CREATED);
            obEvent.setThing(newFile);
            obEvent.setThing2(fileContents);
            listener.reportEvent(obEvent);
        } else if (listener != null && newFile.getName().toLowerCase().endsWith(DOT_BAT)) {
            McpDbWizardEvent obEvent = new McpDbWizardEvent(McpDbWizardEvent.FILE_CREATED);
            obEvent.setThing(newFile);
            obEvent.setThing2(fileContents);
            listener.reportEvent(obEvent);
        }
        //newFile.getName().endsWith(DOT_SH)  || newFile.getName().toLowerCase().endsWith(DOT_BAT)

        return (returnCode);
    }

    public int getCurrentDay() {
        int day = 0;

        if (haveConnection) {
            ReadOnlyRowSet newRowSet = null;
            QueryStatement dayQry = new QueryStatement(SqlStatementDictionary.getDateQuery(), mrLog, mrConnection);

            try {
                newRowSet = dayQry.execute();
                dayQry.releaseResources();
                day = newRowSet.getInt(0);
            } catch (CSException e) {
                day = 0;
                mrLog.syserror(e);
            }

        }
        return (day);
    }

    public String[] getVersionInfo() {
        if (haveConnection && versionInfoArray == null) {
            ReadOnlyRowSet newRowSet = null;
            QueryStatement versionQry = new QueryStatement(SqlStatementDictionary.getVersionQuery(dbProd), mrLog, mrConnection);

            try {
                newRowSet = versionQry.execute();
                versionQry.releaseResources();

                versionInfoArray = new String[newRowSet.size()];

                for (int i = 0; i < versionInfoArray.length; i++) {
                    newRowSet.setCurrentRowNumber(i);
                    versionInfoArray[i] = newRowSet.getString(0);
                }


                mrLog.debugOff();
            } catch (CSException e) {
                versionInfoArray = null;
                mrLog.syserror(e);
            } catch (Exception e) {
                versionInfoArray = null;
                mrLog.syserror(e);
            }

        }
        return (versionInfoArray);
    }

    public String[] getSourceCode(String userName, String objectType, String objectName) {
        String[] sourceCode = new String[0];

        if (haveConnection) {
            ReadOnlyRowSet newRowSet = null;

            String srcQuery = SqlStatementDictionary.plsqlQry;

            if (currentOracleVersion.startsWith("DB2")) {
                srcQuery = SqlStatementDictionary.db2PlsqlQry;
            }

            QueryStatement sourceQry = new QueryStatement(srcQuery, mrLog, mrConnection);
            sourceQry.setUseByteArraysForLongsAndLOBS(true);

    /*
    if (sourceQry == null )
      {
      sourceQry = new QueryStatement(SqlStatementDictionary.plsqlQry, mrLog, mrConnection);
      sourceQry.setCacheRows(100);
      sourceQry.setCacheSeconds(1800);
      }
    else if (! sourceQry.hasResources())
      {
      sourceQry.setConnection(mrConnection);
      }
    */

            try {
                sourceQry.setParam(1, userName);
                sourceQry.setParam(2, objectType);
                sourceQry.setParam(3, objectName);

                newRowSet = sourceQry.execute();
                sourceCode = new String[newRowSet.size()];

                // Handle Function instead of Procedure...
                if (objectType.equalsIgnoreCase("PROCEDURE")
                        && sourceCode.length == 0) {
                    sourceQry.setParam(1, userName);
                    sourceQry.setParam(2, "FUNCTION");
                    sourceQry.setParam(3, objectName);

                    newRowSet = sourceQry.execute();
                    sourceCode = new String[newRowSet.size()];
                }

                sourceQry.releaseResources();

                if (sourceQry.getCacheSize() > 90) {
                    sourceQry.purgeUnderusedCacheEntries(3, 250);
                }

                for (int i = 0; i < sourceCode.length; i++) {
                    newRowSet.setCurrentRowNumber(i);
                    try {
                        sourceCode[i] = newRowSet.getString(0).toUpperCase();
                    } catch (NullPointerException e) {
                        sourceCode[i] = "";
                    }
                }


            } catch (CSException e) {
                sourceCode = null;
                mrLog.syserror(e);
            }

        }
        return (sourceCode);
    }

    public ReadOnlyRowSet getNextAttrArgument(String owner
            , String objectName
            , String packageName
            , String overload
            , int seq
            , int level
            , String realOwner
            , String realName) {
        ReadOnlyRowSet newRowSet = null;
        QueryStatement argQry = null;
        int mode = SqlStatementDictionary.ATTR_ARG_QUERY;

        try {
            if (packageName == null) {
                if (overload == null) {
                    argQry = new QueryStatement(SqlStatementDictionary.getArgQry(currentOracleVersion, mode), mrLog, mrConnection);
                    argQry.setParam(1, realOwner);
                    argQry.setParam(2, objectName);
                    argQry.setParam(3, seq);
                    argQry.setParam(4, getAttrWalkBoundary(realOwner, objectName, null, null, level, seq + 1));
                } else {
                    argQry = new QueryStatement(SqlStatementDictionary.getArgQryOverload(currentOracleVersion, mode), mrLog, mrConnection);
                    argQry.setParam(1, realOwner);
                    argQry.setParam(2, objectName);
                    argQry.setParam(3, seq);
                    argQry.setParam(4, getAttrWalkBoundary(realOwner, objectName, null, null, level, seq + 1));
                }
            } else // pack name not null
            {
                if (overload == null) {
                    argQry = new QueryStatement(SqlStatementDictionary.getArgQryPack(currentOracleVersion, mode), mrLog, mrConnection);
                    argQry.setParam(1, realOwner);
                    argQry.setParam(2, objectName);
                    argQry.setParam(3, packageName);
                    argQry.setParam(4, seq);
                    argQry.setParam(5, getAttrWalkBoundary(realOwner, objectName, packageName, null, level, seq + 1));
                } else {
                    argQry = new QueryStatement(SqlStatementDictionary.getArgQryPackOverload(currentOracleVersion, mode), mrLog, mrConnection);
                    argQry.setParam(1, realOwner);
                    argQry.setParam(2, objectName);
                    argQry.setParam(3, packageName);
                    argQry.setParam(4, overload);
                    argQry.setParam(5, seq);
                    argQry.setParam(6, getAttrWalkBoundary(realOwner, objectName, packageName, overload, level, seq + 1));
                }
            }


            argQry.setKeepFiles(false);
            newRowSet = argQry.execute();

            //mrLog.info(newRowSet.toString());
            argQry.releaseResources();
        } catch (CSException e) {
            mrLog.syserror(e, true, true);
        }

        return (newRowSet);
    }

    public String[] getErrorCode(String userName, String objectType, String objectName) {
        String[] errorCode = new String[0];

        if (haveConnection) {
            ReadOnlyRowSet newRowSet = null;
            QueryStatement errorQry = new QueryStatement(SqlStatementDictionary.getPlsqlErrorQry(currentOracleVersion), mrLog, mrConnection);

            try {
                errorQry.setParam(1, userName);
                errorQry.setParam(2, objectType);
                errorQry.setParam(3, objectName);

                newRowSet = errorQry.execute();
                errorCode = new String[newRowSet.size()];

                // Handle Function instead of Procedure...
                if (objectType.equalsIgnoreCase("PROCEDURE")
                        && errorCode.length == 0) {
                    errorQry.setParam(1, userName);
                    errorQry.setParam(2, "FUNCTION");
                    errorQry.setParam(3, objectName);

                    newRowSet = errorQry.execute();
                    errorCode = new String[newRowSet.size()];
                }

                errorQry.releaseResources();

                for (int i = 0; i < errorCode.length; i++) {
                    newRowSet.setCurrentRowNumber(i);
                    errorCode[i] = newRowSet.getString(0);
                }


            } catch (CSException e) {
                errorCode = null;
                mrLog.syserror(e);
            }

        }
        return (errorCode);
    }

    public String getJavaVersion() {
        return (System.getProperty("java.vm.version"));
    }

    public String getVersion() {
        if (currentOracleVersion == null) {

            if (versionInfoArray != null) {
                for (int i = 0; i < versionInfoArray.length; i++) {
                    if (versionInfoArray[i].startsWith("Oracle")
                            || versionInfoArray[i].startsWith("ORACLE")
                            || versionInfoArray[i]
                            .startsWith("Personal Oracle")
                            || versionInfoArray[i]
                            .startsWith("Personal ORACLE")
                            || versionInfoArray[i]
                            .startsWith("Standard Oracle")
                            || versionInfoArray[i]
                            .startsWith("Standard ORACLE")) {
                        for (int j = 0; j < SqlStatementDictionary.oracleVersions.length; j++) {
                            if (versionInfoArray[i]
                                    .indexOf(SqlStatementDictionary.oracleVersions[j]) > -1) {
                                currentOracleVersion = new String(
                                        SqlStatementDictionary.oracleVersions[j]);

                                break;
                            }
                        }
                        break;
                    }
                }

            }

            if (versionInfoArray != null) {
                // DB2 check
                for (int i = 0; i < versionInfoArray.length; i++) {
                    if (versionInfoArray[i].startsWith("DB2")) {
                        for (int j = 0; j < SqlStatementDictionary.db2Versions.length; j++) {
                            if (versionInfoArray[i]
                                    .indexOf(SqlStatementDictionary.db2Versions[j]) > -1) {
                                currentOracleVersion = new String(
                                        SqlStatementDictionary.db2Versions[j]);


                                break;
                            }
                        }
                        break;
                    }
                }
            }

            if (currentOracleVersion == null && versionInfoArray != null) {
                // Unrecognised but reachable Oracle: 23ai / 26ai banners (e.g.
                // "Oracle AI Database 26ai Free Release 23.26.0.0.0") contain no known
                // version substring, so the loops above leave currentOracleVersion null,
                // which later NPEs on startsWith(...). Fall back to the newest known
                // version's data-dictionary SQL, which is forward-compatible.
                for (int i = 0; i < versionInfoArray.length; i++) {
                    if (versionInfoArray[i] != null
                            && versionInfoArray[i].toUpperCase().indexOf("ORACLE") > -1) {
                        currentOracleVersion = SqlStatementDictionary.oracleVersions[0];
                        break;
                    }
                }
            }
        }
        return (currentOracleVersion);
    }

    void searchDirectoryForOtherFiles(File testDirectory, String testString)
            throws CSException {
        boolean retCode = true;

        if (listener != null) {
            McpDbWizardEvent obEvent = new McpDbWizardEvent(
                    McpDbWizardEvent.CHECK_FOR_OTHER_FILES_REQUESTED);
            obEvent.setThing(testDirectory);
            obEvent.setThing2(testString);
            listener.reportEvent(obEvent);
        }

        if (writePhysicalFiles) {

            File[] fileList = testDirectory.listFiles();

            mrLog.info("Searching " + testDirectory.getAbsolutePath()
                    + " for files not generated by " + Namer.param_prod_name);

            for (int i = 0; i < fileList.length; i++) {

                if (i > 299 && (i % 100) == 0) {
                    mrLog.info("Pre-existing File " + i + " of "
                            + fileList.length + " being checked");
                }

                if (fileList[i].getName().endsWith(".java")
                        && fileList[i].isFile()
                        && (!IOUtils.grep(FILE_TAG, fileList[i]))) {
                    mrLog.warning("File " + fileList[i].getAbsolutePath()
                            + " wasn't generated by " + Namer.param_prod_name);
                    retCode = false;
                }
            }
            mrLog.info("Finished searching " + testDirectory.getAbsolutePath()
                    + " for files not generated by " + Namer.param_prod_name);

            //	if (!retCode) {
            //		throw new CSException(
            //				"One or more files in "
            //						+ testDirectory.getAbsolutePath()
            //						+ " was not generated by " + Namer.param_prod_name + ". Generation halted to prevent harm to human generated code.");
            //
            //	}
        }
    }

